-- или дополнительное образование (85.41). Номер — цифры и дефис.




SELECT doc_id, kind_code, COALESCE(org_inn, person_inn) AS inn,
       COALESCE(org_short_name, last_name || ' ' || first_name) AS name,
       category_code, main_okved_code
FROM msp.v_subject_card;
